insert into asset_version_history (
    id, asset_type, asset_id, project_id, version, change_type, actor,
    changed_fields, diff_json, snapshot_json, trace_id, created_at
) values (
    #{id}, #{assetType}, #{assetId}, #{projectId}, #{version}, #{changeType}, #{actor},
    #{changedFields},
    cast(coalesce(#{diffJson}, '{}') as jsonb),
    cast(coalesce(#{snapshotJson}, '{}') as jsonb),
    #{traceId}, #{createdAt}
)

