insert into asset_link (
    id, source_type, source_id, target_type, target_id, link_type, created_at
)
select #{id}, 'REQUIREMENT', #{requirementId}, 'CASE', #{caseId}, 'VERIFIES', #{createdAt}
where #{caseId} is not null
union all
select gen_random_uuid(), 'REQUIREMENT', #{requirementId}, 'API', #{apiId}, 'COVERS', #{createdAt}
where #{apiId} is not null
on conflict do nothing
